list-partial[enumerate](
    %#0规定为右结合的。#1 应解释为 #2%(
        Type.Expr-UTLC.apply,
        Lambda.apply(x, y, z, w),
        Lambda.apply(
            x,
            parentheses(
                Lambda.apply(y, parentheses(Lambda.apply(z, w)))
            )
        )
    ),
    %运算优先级上 #0较 #1结合更加紧密。#2 应解释为 #3%(Type.Expr-UTLC.apply, Type.Expr-UTLC.lambda, Type.lambda(list-partial[none](@x, @y), Lambda.apply(x, y)),Type.lambda(list-partial[none](@x, @y), parentheses(Lambda.apply(x, y))))
)
